window.VO = [{"id":"n01","text":"You're guarding the groom's shoes.","at":0.24,"t0":0.12,"t1":1.615},{"id":"n02","text":"Because at many North Indian weddings, the bride's sisters steal them, and he pays to get them back.","at":3.67,"t0":1.835,"t1":7.445},{"id":"n03e","text":"It's called joota chupai.","at":15.63,"t0":7.815,"t1":9.39},{"id":"n04","text":"Seven rounds of the fire, five sisters, and a trick every round.","at":20.68,"t0":10.34,"t1":14.12},{"id":"n05","text":"So which one gets his shoes? Pick a number.","at":30.64,"t0":15.32,"t1":17.78},{"id":"n06","text":"Then number five hands you a baby, and nobody says no to a baby.","at":48.16,"t0":24.08,"t1":27.935},{"id":"n07","text":"When you look up, number four's gone, and so are his shoes.","at":56.51,"t0":28.255,"t1":31.31},{"id":"n08","text":"And now they want one lakh.","at":63.42,"t0":31.71,"t1":33.25},{"id":"n09","text":"You laugh.","at":67.4,"t0":33.7,"t1":34.445},{"id":"n10","text":"They walk off.","at":69.49,"t0":34.745,"t1":35.675},{"id":"n11","text":"And no groom leaves barefoot.","at":72.65,"t0":36.325,"t1":37.925},{"id":"n12","text":"So they come down. Fifty-one thousand.","at":77.35,"t0":38.675,"t1":41.005},{"id":"n13","text":"Thirty-one.","at":83.91,"t0":41.955,"t1":42.79},{"id":"n14","text":"Twenty-one.","at":87.48,"t0":43.74,"t1":44.545},{"id":"n15","text":"That's seventy-nine thousand off.","at":90.09,"t0":45.045,"t1":46.855},{"id":"n16","text":"You'd take that, wouldn't you?","at":94.31,"t0":47.155,"t1":48.43},{"id":"n17","text":"He does.","at":98.56,"t0":49.28,"t1":50.055},{"id":"n18","text":"Then they show you their hands.","at":102.36,"t0":51.18,"t1":52.65},{"id":"n19","text":"It's in their mehendi, from last night: twenty-one thousand.","at":106.1,"t0":53.05,"t1":56.14},{"id":"n20","text":"The lakh was only there to make it look small.","at":113.48,"t0":56.74,"t1":58.885},{"id":"n21","text":"You didn't save him a rupee.","at":119.17,"t0":59.585,"t1":61.09},{"id":"n22","text":"And it was on their hands from the start.","at":123.48,"t0":61.74,"t1":63.66}];
